class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        MOD = 10**9 + 7
        subtree_sums = []
        def dfs(node):
            if not node:
                return 0
            s = node.val + dfs(node.left) + dfs(node.right)
            subtree_sums.append(s)
            return s
        total = dfs(root)
        return max(s * (total - s) for s in subtree_sums) % MOD

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        n = len(arr)
        memo = [0] * n
        def dfs(i):
            if memo[i]:
                return memo[i]
            memo[i] = 1
            for di in (-1, 1):
                for j in range(1, d + 1):
                    ni = i + di * j
                    if ni < 0 or ni >= n or arr[ni] >= arr[i]:
                        break
                    memo[i] = max(memo[i], 1 + dfs(ni))
            return memo[i]
        return max(dfs(i) for i in range(n))

