class Solution:
    def maxStudents(self, seats: List[List[str]]) -> int:
        m, n = len(seats), len(seats[0])
        valid = [0] * m
        for i in range(m):
            for j in range(n):
                if seats[i][j] == '.':
                    valid[i] |= 1 << j
        dp = {0: 0}
        for i in range(m):
            new_dp = {}
            for mask in range(1 << n):
                if mask & valid[i] != mask:
                    continue
                if mask & (mask << 1):
                    continue
                cnt = bin(mask).count('1')
                for prev, prev_cnt in dp.items():
                    if (mask << 1) & prev:
                        continue
                    if (mask >> 1) & prev:
                        continue
                    key = mask
                    new_dp[key] = max(new_dp.get(key, 0), prev_cnt + cnt)
            dp = new_dp
        return max(dp.values()) if dp else 0

