                res += 1
            day += 1
        return res

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        import heapq
        total = sum(target)
        heap = [-x for x in target]
        heapq.heapify(heap)
        while True:
            mx = -heapq.heappop(heap)
            if mx == 1:
                return True
            rest = total - mx
            if rest == 0 or rest >= mx:
                return False
            if rest == 1:
                return True
            new_val = mx % rest
            if new_val == 0:
                return False
            total = total - mx + new_val
            heapq.heappush(heap, -new_val)

