class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        indegree = [0] * n
        for i in range(n):
            if leftChild[i] != -1:
                indegree[leftChild[i]] += 1
            if rightChild[i] != -1:
                indegree[rightChild[i]] += 1
        roots = [i for i in range(n) if indegree[i] == 0]
        if len(roots) != 1:
            return False
        from collections import deque
        q = deque([roots[0]])
        visited = set()
        while q:
            node = q.popleft()
            if node in visited:
                return False
            visited.add(node)
            if leftChild[node] != -1:
                q.append(leftChild[node])
            if rightChild[node] != -1:
                q.append(rightChild[node])
        return len(visited) == n

class Solution:
    def closestDivisors(self, num: int) -> List[int]:
        import math
        def find(n):
            for i in range(int(math.isqrt(n)), 0, -1):
                if n % i == 0:
                    return [i, n // i]
        a = find(num + 1)
        b = find(num + 2)
        return a if abs(a[0] - a[1]) <= abs(b[0] - b[1]) else b

class Solution:
    def largestMultipleOfThree(self, digits: List[int]) -> str:
        digits.sort(reverse=True)
        total = sum(digits)
        rem = total % 3
        if rem == 0:
            pass
        else:
            # Try removing one digit with remainder == rem
            found = False
            for i in range(len(digits) - 1, -1, -1):
                if digits[i] % 3 == rem:
                    digits.pop(i)
                    found = True
                    break
            if not found:
                # Remove two digits with remainder == 3 - rem
                target = 3 - rem
                count = 0
                for i in range(len(digits) - 1, -1, -1):
                    if digits[i] % 3 == target:
                        digits.pop(i)
                        count += 1
                        if count == 2:
                            break
        if not digits:
            return ''
        if digits[0] == 0:
            return '0'
        return ''.join(map(str, digits))

