class Solution:
    def isSubPath(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:
        def match(node, curr):
            if not curr:
                return True
            if not node:
                return False
            if node.val != curr.val:
                return False
            return match(node.left, curr.next) or match(node.right, curr.next)
        if not root:
            return False
        return match(root, head) or self.isSubPath(head, root.left) or self.isSubPath(head, root.right)

class Solution:
    def minCost(self, grid: List[List[int]]) -> int:
        from collections import deque
        m, n = len(grid), len(grid[0])
        dirs = [(0,1),(0,-1),(1,0),(-1,0)]  # 1:right,2:left,3:down,4:up
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        dq = deque([(0, 0, 0)])
        while dq:
            d, r, c = dq.popleft()
            if d > dist[r][c]:
                continue
            for i, (dr, dc) in enumerate(dirs):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    cost = 0 if grid[r][c] == i + 1 else 1
                    if d + cost < dist[nr][nc]:
                        dist[nr][nc] = d + cost
                        if cost == 0:
                            dq.appendleft((d, nr, nc))
                        else:
                            dq.append((d + 1, nr, nc))
        return dist[m-1][n-1]

class Solution:
    def sortString(self, s: str) -> str:
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        res = []
        while len(res) < len(s):
            for i in range(26):
                if count[i] > 0:
                    res.append(chr(i + ord('a')))
                    count[i] -= 1
            for i in range(25, -1, -1):
                if count[i] > 0:
                    res.append(chr(i + ord('a')))
                    count[i] -= 1
        return ''.join(res)

class Solution:
    def findTheLongestSubstring(self, s: str) -> int:
        vowels = {'a':0,'e':1,'i':2,'o':3,'u':4}
        first = {0: -1}
        state = 0
        res = 0
        for i, c in enumerate(s):
            if c in vowels:
                state ^= 1 << vowels[c]
            if state in first:
                res = max(res, i - first[state])
            else:
                first[state] = i
        return res

class Solution:
    def longestZigZag(self, root: Optional[TreeNode]) -> int:
        self.res = 0
        def dfs(node, left_len, right_len):
            if not node:
                return
            self.res = max(self.res, left_len, right_len)
            if node.left:
                dfs(node.left, right_len + 1, 0)
            if node.right:
                dfs(node.right, 0, left_len + 1)
        dfs(root, 0, 0)
        return self.res

class Solution:
    def maxSumBST(self, root: Optional[TreeNode]) -> int:
        self.res = 0
        def dfs(node):
            if not node:
                return True, float('inf'), float('-inf'), 0
            l_bst, l_min, l_max, l_sum = dfs(node.left)
            r_bst, r_min, r_max, r_sum = dfs(node.right)
            if l_bst and r_bst and l_max < node.val < r_min:
                s = l_sum + r_sum + node.val
                self.res = max(self.res, s)
                return True, min(l_min, node.val), max(r_max, node.val), s
            return False, 0, 0, 0
        dfs(root)
        return self.res

